"use strict";
const test=require("node:test"),assert=require("node:assert/strict"),fs=require("node:fs"),path=require("node:path");const {fixture}=require("./helper"),{create}=require("../plugin/service");
const definition={name:"Test API",baseUrl:"https://api.example.com",auth:"bearer",secret:"synthetic-credential",allowAgent:true,allowSync:true,operations:[{id:"read",name:"Read",method:"GET",path:"/items/{id}"},{id:"write",name:"Write",method:"POST",path:"/items"}]};
test("Connections owns credentials and uses exact prepared requests with provider approval",async t=>{const requests=[],f=fixture(t,"kai.connections");f.api.network.fetch=async(url,options)=>{requests.push({url,options});return new Response('{"value":"ok"}');};const app=create(f.api);t.after(()=>app.dispose());const c=await app.call("connections.ui.connection",definition),spec=f.provided.get("kai.connections");assert.equal(c.secret,undefined);const prepared=await spec.call("prepare",{connectionId:c.id,operationId:"write",body:{text:"review"},purpose:"agent"});assert.equal(prepared.url,"https://api.example.com/items");await spec.call("execute",{preparedId:prepared.preparedId});assert.equal(f.confirmations.length,1);assert.equal(requests.length,1);assert.equal(requests[0].options.headers.Authorization,"Bearer synthetic-credential");await assert.rejects(spec.call("execute",{connectionId:c.id,operationId:"write",url:"https://evil.example",headers:{Authorization:"steal"}}),/input/i);const state=JSON.parse(f.api.secrets.decryptString(Buffer.from(JSON.parse(fs.readFileSync(path.join(f.root,"state.json"))).encrypted,"base64")));assert.ok(!Object.hasOwn(state,"notes"));assert.ok(!Object.hasOwn(state,"workflows"));assert.ok(!Object.hasOwn(state,"sources"));assert.doesNotMatch(JSON.stringify(await app.call("connections.ui.status")),/synthetic-credential/);});
test("revoked connection revision and denied approval prevent outbound writes",async t=>{const f=fixture(t,"kai.connections"),app=create(f.api);t.after(()=>app.dispose());const c=await app.call("connections.save",definition),spec=f.provided.get("kai.connections"),p=await spec.call("prepare",{connectionId:c.id,operationId:"write",body:{x:1}});await app.call("connections.save",{...definition,id:c.id,name:"Changed"});await assert.rejects(spec.call("execute",{preparedId:p.preparedId}),/changed/);f.api.desktop.confirm=async()=>false;await assert.rejects(spec.call("request",{connectionId:c.id,operationId:"write",body:{x:2}}),/not approved/);});
test("prepared calls are consumer-bound and parallel identical reads do not collide",async t=>{const f=fixture(t,"kai.connections"),app=create(f.api);t.after(()=>app.dispose());const c=await app.call("connections.save",definition),spec=f.provided.get("kai.connections"),input={connectionId:c.id,operationId:"read",variables:{id:"item"},purpose:"workflow"};const a=await spec.call("prepare",input,{caller:"community.reader"}),b=await spec.call("prepare",input,{caller:"community.reader"});assert.equal(a.preparedId,b.preparedId);await assert.rejects(spec.call("execute",{preparedId:a.preparedId},{caller:"other.reader"}),/another app/);await Promise.all([spec.call("execute",{preparedId:a.preparedId},{caller:"community.reader"}),spec.call("execute",{preparedId:b.preparedId},{caller:"community.reader"})]);await assert.rejects(spec.call("execute",{preparedId:a.preparedId},{caller:"community.reader"}),/expired/);await assert.rejects(spec.call("request",{...input,purpose:"skip-grants"}),/purpose/);});
test("managed connection requests use the authenticated Core broker without receiving account tokens",async t=>{const f=fixture(t,"kai.connections"),requests=[];f.api.network.fetch=async(url,options)=>{assert.equal(url,"https://accounts.example.com/connections/status");assert.equal(options.headers,undefined);return new Response(JSON.stringify({available:true,protocol:1,generation:"one"}));};f.api.account={status:()=>({origin:"https://accounts.example.com",signedIn:true,binding:"opaque-session-binding"}),request:async(route,options)=>{requests.push({route,options});return new Response(JSON.stringify({ok:true,result:{userId:"managed-user",accounts:[]}}));}};const app=create(f.api);t.after(()=>app.dispose());await app.call("connections.ui.composioRefresh");assert.deepEqual(requests.map(r=>r.route),["/connections/api/accounts"]);assert.equal(requests[0].options.body.generation,"one");assert.equal(requests[0].options.headers,undefined);assert.equal((await app.call("connections.ui.status")).composio.signedIn,true);f.api.account.status=()=>({origin:"https://accounts.example.com",signedIn:false,binding:"still-an-opaque-binding"});assert.equal((await app.call("connections.ui.status")).composio.signedIn,false);});
